        &&& self.common_pred(nid, data, inst, cb_inst)
        &&& (forall|i|
            #![trigger self.local_updates@[i]]
            0 <= i < self.request_ids@.len() ==> {
                &&& #[trigger] self.local_updates@.contains_key(i)
                &&& self.local_updates@[i].key() == self.request_ids@[i as int]
